    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    bearded_man_patches = [p for p in man_patches if p.verify_property("man", "bearded")]

    if not bearded_man_patches:
        return image_patch

    shirt_patches = image_patch.find("shirt")
    white_shirt_patches = [p for p in shirt_patches if p.verify_property("shirt", "white")]

    if not white_shirt_patches:
        return bearded_man_patches[0]

    min_distance = float('inf')
    target_patch = None

    for bearded_man in bearded_man_patches:
        for white_shirt in white_shirt_patches:
            dist = distance(bearded_man, white_shirt)
            if dist < min_distance:
                min_distance = dist
                target_patch = bearded_man

    return target_patch

